/**
 * @name Taint flow to eval in typing_extensions
 * @description Tracks data flow from public function arguments to eval calls.
 * @kind path-problem
 * @problem.severity error
 * @id py/typing-extensions-eval-taint
 * @tags security
 *       external/cwe/cwe-094
 *       external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EvalTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Parameters of public functions in the main module
    exists(Function f, DataFlow::ParameterNode p |
      f.getName().matches("%") and
      not f.getName().matches("_%") and
      p.getParameter() = f.getArg(_) and
      source = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: Argument to eval
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("eval").getACall() and
      sink = call.getArg(0)
    )
  }
}

module EvalTaintFlow = TaintTracking::Global<EvalTaintConfig>;
import EvalTaintFlow::PathGraph

from EvalTaintFlow::PathNode source, EvalTaintFlow::PathNode sink
where EvalTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection from $@", source.getNode(), "public argument"

/**
 * @name Code injection flow to exec
 * @description Tracing flow from function parameters to exec calls in typing_extensions.py
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-flow
 * @tags security
 *        external/cwe/cwe-094
 *        external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CallNode call |
      call.getFunction().(NameNode).getId() = "exec" and
      sink.asCfgNode() = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "parameter"
